// entities/like/ui/LikeButton.tsx
// 순수한 좋아요 버튼 UI 컴포넌트
export const LikeButton = ({
 isLiked,
 onClick,
}: {
 isLiked: boolean;
 onClick: () => void;
}) => {
 return (
   <button onClick={onClick}>
     {isLiked ? "♥" : "♡"}
   </button>
 );
};

// entities/like/model/types.ts
export interface Like {
 id: string;
 userId: string;
 targetId: string;
 createdAt: Date;
}

// features/videoLike/ui/VideoLikeButton.tsx
// 비디오 좋아요 기능이 부여된 구체적인 기능 컴포넌트
import { LikeButton } from '@/entities/like';

export const VideoLikeButton = ({ videoId }: { videoId: string }) => {
 const [isLiked, setIsLiked] = useState(false);

 const handleLike = async () => {
   try {
     await likeVideo(videoId);
     setIsLiked(true);
     showToast('좋아요를 눌렀습니다');
   } catch (error) {
     showError('좋아요 실패');
   }
 };

 return (
   <LikeButton 
     isLiked={isLiked} 
     onClick={handleLike}
   />
 );
};

// features/videoLike/api/likeApi.ts
export const likeVideo = async (videoId: string) => {
 return await api.post(`/videos/${videoId}/like`);
};

// widgets/videoPlayer/ui/VideoPlayer.tsx
// 비디오 플레이어 위젯에서 좋아요 기능 사용
import { VideoLikeButton } from '@/features/videoLike';

export const VideoPlayer = ({ video }: { video: Video }) => {
 return (
   <div className="video-player">
     <video src={video.url} />
     <div className="controls">
       <PlayButton />
       <VideoLikeButton videoId={video.id} />
       <ShareButton />
     </div>
   </div>
 );
};

